<?php
/**
 * Generated by bin/build.sh --free from pro/licensorpro-client/free-bootstrap.php.tpl
 * (canonical copy: LicensorPro sdk/licensorpro-client/). DO NOT EDIT.
 *
 * Boots the licensing SDK and nothing else, so this build can update itself.
 * It contains no premium code: the --free build deletes pro/ wholesale and puts
 * only pro/licensorpro-client/ back.
 *
 * Why this build exists at all: wordpress.org forbids self-updating plugins, so
 * the Lite build ships no updater. That rule applies to .org, not to a build we
 * hand out ourselves, and with the .org listings closed since 20 Aug the Lite
 * build cannot be updated by anyone, including for security fixes.
 *
 * One template for every JnK plugin, so the free builds behave the same: the
 * same license card in the same place, the same "View details", the same key
 * adoption. Only the identifiers below differ.
 */
if ( ! defined( 'ABSPATH' ) ) { exit; }

$lp_sdk = __DIR__ . '/licensorpro-client/licensorpro-client.php';
if ( ! file_exists( $lp_sdk ) ) { return; }
require_once $lp_sdk;
if ( ! class_exists( 'LicensorPro_Client' ) ) { return; }

$lp_client = new \LicensorPro_Client( [
    'product_slug'   => 'entryvault',
    'plugin_file'    => ENTRYVAULT_FILE,
    'plugin_version' => ENTRYVAULT_VERSION,
    'plugin_name'    => 'EntryVault',
    'text_domain'    => 'entryvault',
    'menu_slug'      => 'entryvault-license',
    // A free build: its licence only exists so it can update itself. No expiry
    // or revoke notices (there are no Pro tools to lock), no "enter your Pro key".
    'pro_build'       => false,
    'licence_notices' => false,
    'card_hook'       => 'entryvault_settings_after',
    'settings_url'    => admin_url( 'admin.php?page=entryvault-settings#lp-entryvault-license' ),
    'support_url'     => 'https://jnkplugins.com/contact',
    'account_url'     => 'https://license.jnkplugins.com/account/licenses',
] );
$lp_client->init();

// An older SDK copy loaded first by another plugin ignores card_hook.
if ( ! method_exists( $lp_client, 'is_free_licence' ) ) {
    add_action( 'entryvault_settings_after', [ $lp_client, 'render_settings_page' ] );
}

/**
 * "View details" on the Plugins screen, when the licence server cannot describe
 * this build. The server renders the popup from the readme.txt of the zip this
 * site would be served (the free zip for a free licence), so its text wins and
 * this only fills what it left empty, or everything when it was unreachable.
 *
 * The local readme goes through the same small, safe subset the server uses:
 * every character escaped first, then = headings =, * lists, **bold**, *italic*,
 * `code`, [links](https://...) and bare URLs; a YouTube URL alone on a line is a
 * linked thumbnail (the popup's wp_kses allows no iframe).
 */
add_filter( 'plugins_api', static function ( $result, $action, $args ) {
    if ( 'plugin_information' !== $action || ! is_object( $args ) || 'entryvault' !== ( $args->slug ?? '' ) ) {
        return $result;
    }
    if ( ! is_object( $result ) && false !== $result ) {
        return $result;
    }
    $readme = dirname( __DIR__ ) . '/readme.txt';
    if ( ! is_readable( $readme ) ) {
        return $result;
    }
    $text = str_replace( [ "\r\n", "\r" ], "\n", (string) file_get_contents( $readme ) );

    $inline = static function ( $s ) {
        $slots = [];
        $put   = static function ( $html ) use ( &$slots ) {
            $slots[] = $html;
            return "\x1A" . ( count( $slots ) - 1 ) . "\x1A";
        };
        $s = str_replace( "\x1A", '', $s );
        $s = preg_replace_callback( '/`([^`]+)`/', static function ( $m ) use ( $put ) {
            return $put( '<code>' . esc_html( $m[1] ) . '</code>' );
        }, $s );
        $s = preg_replace_callback( '/\[([^\]\x1A]+)\]\(\s*(https?:\/\/[^\s)]+)\s*\)/i', static function ( $m ) use ( $put ) {
            return $put( '<a href="' . esc_url( $m[2] ) . '" target="_blank">' . esc_html( $m[1] ) . '</a>' );
        }, $s );
        $s = preg_replace_callback( '/\bhttps?:\/\/[^\s<>"\x1A]+/i', static function ( $m ) use ( $put ) {
            $url  = rtrim( $m[0], '.,;:!?)\'' );
            $tail = substr( $m[0], strlen( $url ) );
            return $put( '<a href="' . esc_url( $url ) . '" target="_blank">' . esc_html( $url ) . '</a>' ) . $tail;
        }, $s );
        $s = esc_html( $s );
        $s = preg_replace( '/\*\*(?=\S)(.+?)(?<=\S)\*\*/u', '<strong>$1</strong>', $s );
        $s = preg_replace( '/(?<![\w*])\*(?=[^\s*])(.+?)(?<=[^\s*])\*(?![\w*])/u', '<em>$1</em>', $s );
        return preg_replace_callback( '/\x1A(\d+)\x1A/', static function ( $m ) use ( $slots ) {
            return $slots[ (int) $m[1] ] ?? '';
        }, $s );
    };

    $render = static function ( $body ) use ( $inline ) {
        $html = [];
        $para = [];
        $list = false;
        $flush = static function () use ( &$para, &$html, $inline ) {
            if ( $para ) {
                $html[] = '<p>' . $inline( implode( ' ', $para ) ) . '</p>';
                $para   = [];
            }
        };
        foreach ( explode( "\n", $body ) as $line ) {
            $line = trim( $line );
            $item = preg_match( '/^[*+-]\s+(\S.*)$/', $line, $im );
            if ( $list && ! $item ) {
                $html[] = '</ul>';
                $list   = false;
            }
            if ( '' === $line ) {
                $flush();
            } elseif ( preg_match( '~^<?https?://(?:(?:www\.|m\.)?youtube(?:-nocookie)?\.com/(?:watch\?(?:[^\s>]*&)?v=|embed/|shorts/)|youtu\.be/)([A-Za-z0-9_-]{11})(?:[?&#/][^\s>]*)?>?$~i', $line, $vm ) ) {
                $flush();
                $html[] = '<p><a href="https://www.youtube.com/watch?v=' . esc_attr( $vm[1] ) . '" target="_blank"><img src="https://i.ytimg.com/vi/' . esc_attr( $vm[1] ) . '/mqdefault.jpg" alt="Watch the video on YouTube"></a><br><a href="https://www.youtube.com/watch?v=' . esc_attr( $vm[1] ) . '" target="_blank">&#9654; Watch the video on YouTube</a></p>';
            } elseif ( preg_match( '/^=\s*([^=].*?)\s*=$/', $line, $hm ) ) {
                $flush();
                $html[] = '<h4>' . $inline( $hm[1] ) . '</h4>';
            } elseif ( $item ) {
                $flush();
                if ( ! $list ) {
                    $html[] = '<ul>';
                    $list   = true;
                }
                $html[] = '<li>' . $inline( $im[1] ) . '</li>';
            } else {
                $para[] = $line;
            }
        }
        $flush();
        if ( $list ) {
            $html[] = '</ul>';
        }
        return implode( "\n", $html );
    };

    $local = [];
    foreach ( [ 'description' => 'Description', 'installation' => 'Installation', 'faq' => 'Frequently Asked Questions', 'changelog' => 'Changelog' ] as $key => $heading ) {
        if ( preg_match( '/^==\s*' . preg_quote( $heading, '/' ) . '\s*==\s*$(.*?)(?=^==\s|\z)/ms', $text, $m ) && '' !== trim( $m[1] ) ) {
            $local[ $key ] = $render( trim( $m[1] ) );
        }
    }

    if ( false === $result ) {
        // The licence server did not answer: describe this build from its own files.
        $result = (object) [
            'name'     => 'EntryVault',
            'slug'     => 'entryvault',
            'version'  => defined( 'ENTRYVAULT_VERSION' ) ? ENTRYVAULT_VERSION : '',
            'sections' => [],
        ];
        foreach ( [ 'requires' => 'Requires at least', 'tested' => 'Tested up to', 'requires_php' => 'Requires PHP' ] as $field => $label ) {
            if ( preg_match( '/^' . $label . ':\s*([0-9.]+)\s*$/mi', $text, $fm ) ) {
                $result->$field = $fm[1];
            }
        }
    }

    $sections = (array) ( $result->sections ?? [] );
    foreach ( $local as $key => $html ) {
        if ( '' === trim( wp_strip_all_tags( (string) ( $sections[ $key ] ?? '' ) ) ) && false === strpos( (string) ( $sections[ $key ] ?? '' ), '<img' ) ) {
            $sections[ $key ] = $html;
        }
    }
    // A filled-in gap went to the end, after Screenshots: keep wordpress.org's tab order.
    $order    = array_flip( [ 'description', 'installation', 'faq', 'screenshots', 'changelog', 'reviews', 'other_notes' ] );
    $position = array_flip( array_keys( $sections ) );
    uksort( $sections, static function ( $a, $b ) use ( $order, $position ) {
        return ( $order[ $a ] ?? 50 + $position[ $a ] ) <=> ( $order[ $b ] ?? 50 + $position[ $b ] );
    } );
    $result->sections = $sections;

    // The short description: the first line after the header block, before any "== Section ==".
    $head = (string) preg_split( '/^==\s/m', $text, 2 )[0];
    $head = (string) preg_replace( '/^===.*===\s*$|^[A-Za-z ]+:.*$/m', '', $head );
    if ( '' === trim( (string) ( $result->short_description ?? '' ) ) && preg_match( '/^\s*(\S.*?)\s*$/m', $head, $short ) ) {
        $result->short_description = wp_strip_all_tags( $short[1] );
    }
    return $result;
}, 20, 3 );

/**
 * Adopt the licence key stamped into this zip at download time.
 *
 * The key is bound to the site by activate(), not merely stored: storing the
 * option alone would leave the install unactivated and every update check would
 * be refused.
 *
 * Runs once. A failure is retried on a later admin request rather than looped:
 * the licence server being briefly unreachable must not turn into a request per
 * page load.
 */
add_action( 'admin_init', static function () use ( $lp_client ) {
    $opt = 'licensorpro_' . 'entryvault' . '_key';
    if ( '' !== (string) get_option( $opt, '' ) ) { return; }

    $attempted = 'licensorpro_entryvault_free_claimed';
    if ( get_transient( $attempted ) ) { return; }

    $stamp = dirname( __DIR__ ) . '/licensorpro-free.json';
    if ( ! file_exists( $stamp ) ) { return; }

    $data = json_decode( (string) file_get_contents( $stamp ), true );
    $key  = is_array( $data ) ? (string) ( $data['license_key'] ?? '' ) : '';
    if ( '' === $key ) { return; }

    set_transient( $attempted, 1, HOUR_IN_SECONDS );
    $lp_client->activate( $key );
}, 20 );
